-- Banco de preguntas oficial, lote 01. Reejecutable sin duplicados.
BEGIN;
ALTER TABLE public.banco_preguntas ADD COLUMN IF NOT EXISTS "FUENTE" text;
ALTER TABLE public.banco_preguntas ADD COLUMN IF NOT EXISTS "PAGINAS_PDF" text;
WITH payload AS (
  SELECT * FROM jsonb_to_recordset('[{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"Una persona está sana y recibe una vacuna. ¿Qué se intenta evitar?","OPCION_A":"Que la salud también depende de condiciones del entorno, no solo de decisiones individuales.","OPCION_B":"Reducir secuelas y recuperar funciones; es prevención terciaria.","OPCION_C":"Que la enfermedad aparezca; por eso es prevención primaria.","OPCION_D":"Que la población acceda a servicios adecuados y que las intervenciones se evalúen.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Que la enfermedad aparezca; por eso es prevención primaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"¿En qué momento actúa la prevención primaria?","OPCION_A":"Prevención terciaria, porque intenta reducir secuelas de una enfermedad establecida.","OPCION_B":"Antes de que aparezca la enfermedad, reduciendo la exposición a sus factores de riesgo.","OPCION_C":"Prevención primaria, porque actúa antes de que se produzca la enfermedad.","OPCION_D":"Encontrar la enfermedad a tiempo para tratarla antes de que progrese: prevención secundaria.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Antes de que aparezca la enfermedad, reduciendo la exposición a sus factores de riesgo.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"medio","PREGUNTA":"Si una comunidad mejora el acceso a agua segura para evitar infecciones, ¿qué prevención realiza?","OPCION_A":"Prevención secundaria.","OPCION_B":"Prevención terciaria.","OPCION_C":"Prevención primaria, porque actúa antes de que se produzca la enfermedad.","OPCION_D":"Prevención cuaternaria.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Prevención primaria, porque actúa antes de que se produzca la enfermedad.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"¿Qué busca un programa de detección temprana del cáncer cervicouterino?","OPCION_A":"Disminuir sus consecuencias y favorecer la recuperación funcional; corresponde a prevención terciaria.","OPCION_B":"Antes de que aparezca la enfermedad, reduciendo la exposición a sus factores de riesgo.","OPCION_C":"Encontrar la enfermedad a tiempo para tratarla antes de que progrese: prevención secundaria.","OPCION_D":"Prevención terciaria, porque intenta reducir secuelas de una enfermedad establecida.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Encontrar la enfermedad a tiempo para tratarla antes de que progrese: prevención secundaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué un tamizaje no se considera prevención primaria?","OPCION_A":"Porque busca una enfermedad que ya podría estar presente, aunque todavía no cause síntomas.","OPCION_B":"Porque protege antes de que la persona contraiga la enfermedad que se quiere evitar.","OPCION_C":"Antes de que aparezca la enfermedad, reduciendo la exposición a sus factores de riesgo.","OPCION_D":"Porque todas las personas deben tener oportunidades y condiciones dignas para alcanzar bienestar.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Porque busca una enfermedad que ya podría estar presente, aunque todavía no cause síntomas.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"Una prueba de VIH permite iniciar tratamiento oportuno. ¿Qué nivel de prevención representa la detección?","OPCION_A":"Prevención secundaria.","OPCION_B":"Prevención primaria.","OPCION_C":"Prevención terciaria.","OPCION_D":"Prevención cuaternaria.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Prevención secundaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"Una persona ya tuvo un infarto y empieza rehabilitación. ¿Cuál es el objetivo preventivo?","OPCION_A":"Prevención terciaria, porque intenta reducir secuelas de una enfermedad establecida.","OPCION_B":"A la prevención secundaria.","OPCION_C":"Reducir secuelas y recuperar funciones; es prevención terciaria.","OPCION_D":"Prevención primaria, porque actúa antes de que se produzca la enfermedad.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Reducir secuelas y recuperar funciones; es prevención terciaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"¿En qué se diferencia la prevención terciaria de la secundaria?","OPCION_A":"La promoción fortalece condiciones y capacidades para el bienestar; la prevención se centra en riesgos y enfermedades.","OPCION_B":"La prevención cuaternaria, que busca evitar daños por exceso de intervención médica.","OPCION_C":"La secundaria busca detectar y tratar temprano; la terciaria limita complicaciones de una enfermedad ya establecida.","OPCION_D":"El sobrediagnóstico y el sobretratamiento.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La secundaria busca detectar y tratar temprano; la terciaria limita complicaciones de una enfermedad ya establecida.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"¿Qué pretende la reinserción social tras una enfermedad mental?","OPCION_A":"Encontrar la enfermedad a tiempo para tratarla antes de que progrese: prevención secundaria.","OPCION_B":"Disminuir sus consecuencias y favorecer la recuperación funcional; corresponde a prevención terciaria.","OPCION_C":"Antes de que aparezca la enfermedad, reduciendo la exposición a sus factores de riesgo.","OPCION_D":"Prevención terciaria, porque intenta reducir secuelas de una enfermedad establecida.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Disminuir sus consecuencias y favorecer la recuperación funcional; corresponde a prevención terciaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"Un examen sin indicación puede iniciar tratamientos innecesarios. ¿Qué nivel de prevención pide detenerse?","OPCION_A":"Prevención primaria.","OPCION_B":"La prevención cuaternaria, que busca evitar daños por exceso de intervención médica.","OPCION_C":"Prevención secundaria.","OPCION_D":"Prevención terciaria.","RESPUESTA_CORRECTA":"B","EXPLICACION":"La prevención cuaternaria, que busca evitar daños por exceso de intervención médica.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"¿Qué dos riesgos intenta reducir la prevención cuaternaria?","OPCION_A":"La promoción fortalece condiciones y capacidades para el bienestar; la prevención se centra en riesgos y enfermedades.","OPCION_B":"La prevención cuaternaria, que busca evitar daños por exceso de intervención médica.","OPCION_C":"El sobrediagnóstico y el sobretratamiento.","OPCION_D":"La secundaria busca detectar y tratar temprano; la terciaria limita complicaciones de una enfermedad ya establecida.","RESPUESTA_CORRECTA":"C","EXPLICACION":"El sobrediagnóstico y el sobretratamiento.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"facil","PREGUNTA":"Una citología cervical busca identificar lesiones tempranas. ¿A qué nivel corresponde?","OPCION_A":"Prevención terciaria.","OPCION_B":"A la prevención secundaria.","OPCION_C":"Prevención primaria.","OPCION_D":"Prevención cuaternaria.","RESPUESTA_CORRECTA":"B","EXPLICACION":"A la prevención secundaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia central hay entre promoción de la salud y prevención de una enfermedad?","OPCION_A":"La secundaria busca detectar y tratar temprano; la terciaria limita complicaciones de una enfermedad ya establecida.","OPCION_B":"El sobrediagnóstico y el sobretratamiento.","OPCION_C":"La prevención cuaternaria, que busca evitar daños por exceso de intervención médica.","OPCION_D":"La promoción fortalece condiciones y capacidades para el bienestar; la prevención se centra en riesgos y enfermedades.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La promoción fortalece condiciones y capacidades para el bienestar; la prevención se centra en riesgos y enfermedades.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"medio","PREGUNTA":"Si se busca reducir la discapacidad después de una enfermedad, ¿qué nivel se está aplicando?","OPCION_A":"Prevención primaria.","OPCION_B":"A la prevención secundaria.","OPCION_C":"Prevención cuaternaria.","OPCION_D":"Prevención terciaria.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Prevención terciaria.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"niveles de prevencion","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué la vacunación es un ejemplo clásico de prevención primaria?","OPCION_A":"Porque busca una enfermedad que ya podría estar presente, aunque todavía no cause síntomas.","OPCION_B":"Porque también incluye promoción, prevención, rehabilitación y seguimiento integral.","OPCION_C":"Porque protege antes de que la persona contraiga la enfermedad que se quiere evitar.","OPCION_D":"Antes de que aparezca la enfermedad, reduciendo la exposición a sus factores de riesgo.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Porque protege antes de que la persona contraiga la enfermedad que se quiere evitar.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"18–20"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"medio","PREGUNTA":"Según la Carta de Ottawa, ¿qué debe ganar una persona para mejorar su salud?","OPCION_A":"Mayor capacidad y medios para controlar los factores que influyen en ella.","OPCION_B":"Dar más espacio a la promoción y a la atención primaria, además de la atención curativa.","OPCION_C":"Apoyar y facilitar que personas y comunidades mejoren sus condiciones de salud.","OPCION_D":"Puede perder participación real y convertirse en una acción asistencialista.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Mayor capacidad y medios para controlar los factores que influyen en ella.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"facil","PREGUNTA":"Un barrio pide iluminación y espacios seguros para caminar. ¿Qué área de promoción refleja?","OPCION_A":"Desarrollar habilidades personales.","OPCION_B":"Actuar sobre causas sociales, ambientales y conductuales que influyen en la salud.","OPCION_C":"Crear ambientes que favorezcan la salud.","OPCION_D":"Apoyar y facilitar que personas y comunidades mejoren sus condiciones de salud.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Crear ambientes que favorezcan la salud.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"medio","PREGUNTA":"Si una comunidad decide sus prioridades sanitarias junto al equipo de salud, ¿qué se fortalece?","OPCION_A":"La construcción de políticas públicas saludables.","OPCION_B":"La investigación cualitativa participativa o investigación-acción.","OPCION_C":"La independiente; el resultado se considera dependiente.","OPCION_D":"La acción comunitaria y la participación en las decisiones.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La acción comunitaria y la participación en las decisiones.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"medio","PREGUNTA":"¿Qué pasa si un programa se diseña sin escuchar a la comunidad?","OPCION_A":"Apoyar y facilitar que personas y comunidades mejoren sus condiciones de salud.","OPCION_B":"Puede perder participación real y convertirse en una acción asistencialista.","OPCION_C":"Dar más espacio a la promoción y a la atención primaria, además de la atención curativa.","OPCION_D":"Políticas saludables, ambientes favorables, acción comunitaria, habilidades personales y reorientación de servicios.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Puede perder participación real y convertirse en una acción asistencialista.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"facil","PREGUNTA":"Un municipio revisa el efecto de sus decisiones de transporte sobre la salud. ¿Qué área aplica?","OPCION_A":"La construcción de políticas públicas saludables.","OPCION_B":"La acción comunitaria y la participación en las decisiones.","OPCION_C":"Crear ambientes que favorezcan la salud.","OPCION_D":"La población concreta que será investigada.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La construcción de políticas públicas saludables.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"facil","PREGUNTA":"En una escuela enseñan habilidades para elegir alimentos saludables. ¿Qué área de promoción es?","OPCION_A":"Crear ambientes que favorezcan la salud.","OPCION_B":"Actuar sobre causas sociales, ambientales y conductuales que influyen en la salud.","OPCION_C":"Desarrollar habilidades personales.","OPCION_D":"Apoyar y facilitar que personas y comunidades mejoren sus condiciones de salud.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Desarrollar habilidades personales.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué significa reorientar los servicios de salud en la Carta de Ottawa?","OPCION_A":"Dar más espacio a la promoción y a la atención primaria, además de la atención curativa.","OPCION_B":"Políticas saludables, ambientes favorables, acción comunitaria, habilidades personales y reorientación de servicios.","OPCION_C":"Apoyar y facilitar que personas y comunidades mejoren sus condiciones de salud.","OPCION_D":"Puede perder participación real y convertirse en una acción asistencialista.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Dar más espacio a la promoción y a la atención primaria, además de la atención curativa.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué la educación y la legislación pueden trabajar juntas en promoción?","OPCION_A":"Porque la población identifica sus necesidades y ayuda a decidir y sostener las acciones.","OPCION_B":"Porque educación, vivienda, trabajo y otros sectores también determinan las oportunidades de estar sano.","OPCION_C":"Porque la promoción combina métodos complementarios para cambiar capacidades y condiciones de vida.","OPCION_D":"Porque la participación comunitaria ayuda a reconocer necesidades y a tomar decisiones pertinentes.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Porque la promoción combina métodos complementarios para cambiar capacidades y condiciones de vida.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"medio","PREGUNTA":"Una familia no puede elegir agua segura si su barrio carece de ella. ¿Qué recuerda este caso?","OPCION_A":"Que la salud también depende de condiciones del entorno, no solo de decisiones individuales.","OPCION_B":"Que las personas participen y encuentren formas propias de mejorar la salud de su comunidad.","OPCION_C":"Que se construyan políticas saludables y se consideren los efectos de las decisiones sobre la salud.","OPCION_D":"Que la enfermedad aparezca; por eso es prevención primaria.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Que la salud también depende de condiciones del entorno, no solo de decisiones individuales.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué papel tiene el personal de atención primaria en promoción de la salud?","OPCION_A":"Dar más espacio a la promoción y a la atención primaria, además de la atención curativa.","OPCION_B":"Puede perder participación real y convertirse en una acción asistencialista.","OPCION_C":"Apoyar y facilitar que personas y comunidades mejoren sus condiciones de salud.","OPCION_D":"Políticas saludables, ambientes favorables, acción comunitaria, habilidades personales y reorientación de servicios.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Apoyar y facilitar que personas y comunidades mejoren sus condiciones de salud.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"facil","PREGUNTA":"¿Cuál es el foco de la promoción cuando habla de determinantes?","OPCION_A":"Apoyar y facilitar que personas y comunidades mejoren sus condiciones de salud.","OPCION_B":"Dar más espacio a la promoción y a la atención primaria, además de la atención curativa.","OPCION_C":"Puede perder participación real y convertirse en una acción asistencialista.","OPCION_D":"Actuar sobre causas sociales, ambientales y conductuales que influyen en la salud.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Actuar sobre causas sociales, ambientales y conductuales que influyen en la salud.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué la promoción requiere colaboración fuera del consultorio?","OPCION_A":"Porque la promoción combina métodos complementarios para cambiar capacidades y condiciones de vida.","OPCION_B":"Porque la población identifica sus necesidades y ayuda a decidir y sostener las acciones.","OPCION_C":"Porque proteger a una población exige coordinar información, recursos, servicios y decisiones colectivas.","OPCION_D":"Porque educación, vivienda, trabajo y otros sectores también determinan las oportunidades de estar sano.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Porque educación, vivienda, trabajo y otros sectores también determinan las oportunidades de estar sano.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué busca la autoayuda comunitaria dentro de la promoción?","OPCION_A":"Que se construyan políticas saludables y se consideren los efectos de las decisiones sobre la salud.","OPCION_B":"Que las personas participen y encuentren formas propias de mejorar la salud de su comunidad.","OPCION_C":"Que la salud también depende de condiciones del entorno, no solo de decisiones individuales.","OPCION_D":"Que las personas desarrollen habilidades y adopten prácticas saludables de manera sostenida.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Que las personas participen y encuentren formas propias de mejorar la salud de su comunidad.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"promocion de la salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué cinco áreas de acción resume la Carta de Ottawa?","OPCION_A":"Políticas saludables, ambientes favorables, acción comunitaria, habilidades personales y reorientación de servicios.","OPCION_B":"Dar más espacio a la promoción y a la atención primaria, además de la atención curativa.","OPCION_C":"Apoyar y facilitar que personas y comunidades mejoren sus condiciones de salud.","OPCION_D":"Puede perder participación real y convertirse en una acción asistencialista.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Políticas saludables, ambientes favorables, acción comunitaria, habilidades personales y reorientación de servicios.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"14–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"Una familia consulta primero en su centro de salud cercano. ¿Qué función cumple la atención primaria?","OPCION_A":"Acompañar a la persona o familia a lo largo del tiempo, no solo en una consulta aislada.","OPCION_B":"Ser el primer contacto de la persona, la familia y la comunidad con el sistema de salud.","OPCION_C":"Conectar acciones del equipo y de los distintos niveles para mantener la continuidad de la atención.","OPCION_D":"Comprobar los efectos de la atención, como salud, satisfacción, equidad y uso de recursos.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Ser el primer contacto de la persona, la familia y la comunidad con el sistema de salud.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué pide Alma-Ata sobre la participación de la comunidad en atención primaria?","OPCION_A":"Que las personas participen y encuentren formas propias de mejorar la salud de su comunidad.","OPCION_B":"Que las personas desarrollen habilidades y adopten prácticas saludables de manera sostenida.","OPCION_C":"Que las personas puedan recibir servicios de salud necesarios sin quedar excluidas por barreras de acceso.","OPCION_D":"Que las personas y familias participen plenamente en una atención esencial y accesible.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Que las personas y familias participen plenamente en una atención esencial y accesible.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"Un servicio está lejos y el transporte es caro. ¿Qué atributo de atención primaria falla?","OPCION_A":"La accesibilidad, porque hay barreras geográficas y económicas.","OPCION_B":"Coordinación","OPCION_C":"Integralidad","OPCION_D":"Longitudinalidad","RESPUESTA_CORRECTA":"A","EXPLICACION":"La accesibilidad, porque hay barreras geográficas y económicas.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"El centro de salud adapta la atención a la lengua de la familia. ¿Qué barrera está reduciendo?","OPCION_A":"La atención primaria de salud.","OPCION_B":"El individuo, la familia y la comunidad.","OPCION_C":"Una barrera cultural de acceso.","OPCION_D":"La accesibilidad, porque hay barreras geográficas y económicas.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Una barrera cultural de acceso.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué significa coordinación en la atención primaria?","OPCION_A":"Conectar acciones del equipo y de los distintos niveles para mantener la continuidad de la atención.","OPCION_B":"Acompañar a la persona o familia a lo largo del tiempo, no solo en una consulta aislada.","OPCION_C":"Accesibilidad, coordinación, integralidad y longitudinalidad.","OPCION_D":"Ser el primer contacto de la persona, la familia y la comunidad con el sistema de salud.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Conectar acciones del equipo y de los distintos niveles para mantener la continuidad de la atención.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"Un equipo atiende prevención, tratamiento y rehabilitación. ¿Qué atributo demuestra?","OPCION_A":"Accesibilidad","OPCION_B":"Integralidad.","OPCION_C":"Coordinación","OPCION_D":"Longitudinalidad","RESPUESTA_CORRECTA":"B","EXPLICACION":"Integralidad.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué ver a la misma familia a lo largo de los años aporta valor?","OPCION_A":"Ser el primer contacto de la persona, la familia y la comunidad con el sistema de salud.","OPCION_B":"Favorece la longitudinalidad: conocer su historia y acompañar sus problemas en el tiempo.","OPCION_C":"Comprobar los efectos de la atención, como salud, satisfacción, equidad y uso de recursos.","OPCION_D":"Acompañar a la persona o familia a lo largo del tiempo, no solo en una consulta aislada.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Favorece la longitudinalidad: conocer su historia y acompañar sus problemas en el tiempo.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia hay entre accesibilidad y longitudinalidad?","OPCION_A":"La primera permite llegar al servicio; la segunda mantiene el seguimiento a lo largo del tiempo.","OPCION_B":"El individuo, la familia y la comunidad.","OPCION_C":"La atención primaria de salud.","OPCION_D":"La continuidad de la atención mediante coordinación entre niveles.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La primera permite llegar al servicio; la segunda mantiene el seguimiento a lo largo del tiempo.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"Al evaluar un centro, ¿qué significa mirar su estructura?","OPCION_A":"Revisar recursos como personal, infraestructura, equipos e insumos.","OPCION_B":"Observar las actividades y procedimientos que realiza el equipo para brindar atención.","OPCION_C":"Comprobar los efectos de la atención, como salud, satisfacción, equidad y uso de recursos.","OPCION_D":"De proceso: falla la forma en que se coordinan las acciones de atención.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Revisar recursos como personal, infraestructura, equipos e insumos.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"Al evaluar un centro, ¿qué significa mirar su proceso?","OPCION_A":"Observar las actividades y procedimientos que realiza el equipo para brindar atención.","OPCION_B":"Comprobar los efectos de la atención, como salud, satisfacción, equidad y uso de recursos.","OPCION_C":"Revisar recursos como personal, infraestructura, equipos e insumos.","OPCION_D":"Acompañar a la persona o familia a lo largo del tiempo, no solo en una consulta aislada.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Observar las actividades y procedimientos que realiza el equipo para brindar atención.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"Al evaluar un centro, ¿qué significa mirar sus resultados?","OPCION_A":"Comprobar los efectos de la atención, como salud, satisfacción, equidad y uso de recursos.","OPCION_B":"Observar las actividades y procedimientos que realiza el equipo para brindar atención.","OPCION_C":"Revisar recursos como personal, infraestructura, equipos e insumos.","OPCION_D":"Acompañar a la persona o familia a lo largo del tiempo, no solo en una consulta aislada.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Comprobar los efectos de la atención, como salud, satisfacción, equidad y uso de recursos.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"Hay equipos, pero las derivaciones se pierden. ¿El problema principal es de estructura o proceso?","OPCION_A":"De proceso: falla la forma en que se coordinan las acciones de atención.","OPCION_B":"Revisar recursos como personal, infraestructura, equipos e insumos.","OPCION_C":"Observar las actividades y procedimientos que realiza el equipo para brindar atención.","OPCION_D":"Accesibilidad, coordinación, integralidad y longitudinalidad.","RESPUESTA_CORRECTA":"A","EXPLICACION":"De proceso: falla la forma en que se coordinan las acciones de atención.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué la atención primaria no equivale solo a curar enfermedades leves?","OPCION_A":"Porque también influyen condiciones sociales, económicas y ambientales que limitan sus opciones.","OPCION_B":"Porque también incluye promoción, prevención, rehabilitación y seguimiento integral.","OPCION_C":"Favorece la longitudinalidad: conocer su historia y acompañar sus problemas en el tiempo.","OPCION_D":"Porque protege antes de que la persona contraiga la enfermedad que se quiere evitar.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Porque también incluye promoción, prevención, rehabilitación y seguimiento integral.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué tres ámbitos se mencionan como primer contacto con la atención primaria?","OPCION_A":"El individuo, la familia y la comunidad.","OPCION_B":"La atención primaria de salud.","OPCION_C":"La primera permite llegar al servicio; la segunda mantiene el seguimiento a lo largo del tiempo.","OPCION_D":"Una barrera cultural de acceso.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El individuo, la familia y la comunidad.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"Un paciente recibe una derivación y después continúa sus controles en el centro. ¿Qué se conserva?","OPCION_A":"La continuidad de la atención mediante coordinación entre niveles.","OPCION_B":"La accesibilidad, porque hay barreras geográficas y económicas.","OPCION_C":"La primera permite llegar al servicio; la segunda mantiene el seguimiento a lo largo del tiempo.","OPCION_D":"El individuo, la familia y la comunidad.","RESPUESTA_CORRECTA":"A","EXPLICACION":"La continuidad de la atención mediante coordinación entre niveles.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"atencion primaria de salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué cuatro atributos básicos debes reconocer en la atención primaria?","OPCION_A":"Coordinación","OPCION_B":"Integralidad","OPCION_C":"Accesibilidad, coordinación, integralidad y longitudinalidad.","OPCION_D":"Longitudinalidad","RESPUESTA_CORRECTA":"C","EXPLICACION":"Accesibilidad, coordinación, integralidad y longitudinalidad.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"16–18"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"medio","PREGUNTA":"Después de una charla, un grupo sabe qué hacer pero no puede practicarlo. ¿Qué le falta a la educación en salud?","OPCION_A":"Ayuda a reconocer riesgos y a adoptar prácticas que disminuyan la posibilidad de enfermar.","OPCION_B":"Fortalece capacidades personales y comunitarias para mejorar condiciones de bienestar.","OPCION_C":"Ayudar a desarrollar habilidades y condiciones para convertir lo aprendido en prácticas sostenibles.","OPCION_D":"Tomar decisiones informadas y participar activamente en el cuidado propio, familiar y comunitario.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Ayudar a desarrollar habilidades y condiciones para convertir lo aprendido en prácticas sostenibles.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"facil","PREGUNTA":"¿A quiénes incluye la educación en salud además de cada paciente?","OPCION_A":"A las familias y a las comunidades.","OPCION_B":"Conocimientos, actitudes y prácticas.","OPCION_C":"Con la promoción de la salud y la prevención de enfermedades.","OPCION_D":"Fortalece capacidades personales y comunitarias para mejorar condiciones de bienestar.","RESPUESTA_CORRECTA":"A","EXPLICACION":"A las familias y a las comunidades.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué tres aspectos de la persona intenta transformar la educación en salud?","OPCION_A":"A las familias y a las comunidades.","OPCION_B":"Tomar decisiones informadas y participar activamente en el cuidado propio, familiar y comunitario.","OPCION_C":"Conocimientos, actitudes y prácticas.","OPCION_D":"Con la promoción de la salud y la prevención de enfermedades.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Conocimientos, actitudes y prácticas.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"facil","PREGUNTA":"Una estudiante explica el lavado de manos y luego practica con su comunidad. ¿Qué aporta la segunda parte?","OPCION_A":"Participa activamente en su aprendizaje y en el cuidado colectivo de la salud.","OPCION_B":"Con la promoción de la salud y la prevención de enfermedades.","OPCION_C":"Pasa de la información a una habilidad y una práctica concreta.","OPCION_D":"Capacidad de autogestión y mayor control sobre los factores que afectan su bienestar.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Pasa de la información a una habilidad y una práctica concreta.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué se habla de un proceso permanente de educación en salud?","OPCION_A":"Para escuchar dudas y experiencias de la comunidad, además de compartir información.","OPCION_B":"Porque la posibilidad de practicarla depende también de recursos, costumbres y condiciones de vida.","OPCION_C":"Porque aprender y ajustar conductas saludables requiere continuidad y reflexión, no una sola charla.","OPCION_D":"Porque los hábitos también dependen del entorno y de condiciones sociales; la educación debe acompañarse de acciones más amplias.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Porque aprender y ajustar conductas saludables requiere continuidad y reflexión, no una sola charla.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué significa autogestionar la salud?","OPCION_A":"Tomar decisiones informadas y participar activamente en el cuidado propio, familiar y comunitario.","OPCION_B":"Ayuda a reconocer riesgos y a adoptar prácticas que disminuyan la posibilidad de enfermar.","OPCION_C":"Fortalece capacidades personales y comunitarias para mejorar condiciones de bienestar.","OPCION_D":"Conocimientos, actitudes y prácticas.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Tomar decisiones informadas y participar activamente en el cuidado propio, familiar y comunitario.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"medio","PREGUNTA":"Si una campaña ignora costumbres locales, ¿qué dimensión importante está dejando fuera?","OPCION_A":"Un estilo de vida saludable con cuidado personal, familiar y comunitario.","OPCION_B":"El enfoque biopsicosocial.","OPCION_C":"Capacidad de autogestión y mayor control sobre los factores que afectan su bienestar.","OPCION_D":"El contexto cultural y social en el que las personas aprenden y toman decisiones.","RESPUESTA_CORRECTA":"D","EXPLICACION":"El contexto cultural y social en el que las personas aprenden y toman decisiones.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué la comunicación en educación para la salud debe ir en ambos sentidos?","OPCION_A":"Porque aprender y ajustar conductas saludables requiere continuidad y reflexión, no una sola charla.","OPCION_B":"Porque la posibilidad de practicarla depende también de recursos, costumbres y condiciones de vida.","OPCION_C":"Porque los hábitos también dependen del entorno y de condiciones sociales; la educación debe acompañarse de acciones más amplias.","OPCION_D":"Para escuchar dudas y experiencias de la comunidad, además de compartir información.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Para escuchar dudas y experiencias de la comunidad, además de compartir información.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué enfoque reconoce factores biológicos, psicológicos y sociales al educar en salud?","OPCION_A":"El enfoque biopsicosocial.","OPCION_B":"Un estilo de vida saludable con cuidado personal, familiar y comunitario.","OPCION_C":"El contexto cultural y social en el que las personas aprenden y toman decisiones.","OPCION_D":"Conocimientos, actitudes y prácticas.","RESPUESTA_CORRECTA":"A","EXPLICACION":"El enfoque biopsicosocial.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué busca el empoderamiento de la comunidad en educación sanitaria?","OPCION_A":"Que pueda comprender opciones y participar en decisiones que afectan su bienestar.","OPCION_B":"Que las personas desarrollen habilidades y adopten prácticas saludables de manera sostenida.","OPCION_C":"Un estilo de vida saludable con cuidado personal, familiar y comunitario.","OPCION_D":"Tomar decisiones informadas y participar activamente en el cuidado propio, familiar y comunitario.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Que pueda comprender opciones y participar en decisiones que afectan su bienestar.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"facil","PREGUNTA":"¿Cómo se relaciona la educación en salud con la prevención?","OPCION_A":"Ayuda a reconocer riesgos y a adoptar prácticas que disminuyan la posibilidad de enfermar.","OPCION_B":"Fortalece capacidades personales y comunitarias para mejorar condiciones de bienestar.","OPCION_C":"Con la promoción de la salud y la prevención de enfermedades.","OPCION_D":"Tomar decisiones informadas y participar activamente en el cuidado propio, familiar y comunitario.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Ayuda a reconocer riesgos y a adoptar prácticas que disminuyan la posibilidad de enfermar.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"facil","PREGUNTA":"¿Cómo se relaciona la educación en salud con la promoción?","OPCION_A":"Fortalece capacidades personales y comunitarias para mejorar condiciones de bienestar.","OPCION_B":"Ayuda a reconocer riesgos y a adoptar prácticas que disminuyan la posibilidad de enfermar.","OPCION_C":"Con la promoción de la salud y la prevención de enfermedades.","OPCION_D":"Tomar decisiones informadas y participar activamente en el cuidado propio, familiar y comunitario.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Fortalece capacidades personales y comunitarias para mejorar condiciones de bienestar.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué enseñar una conducta saludable sin considerar el entorno puede fallar?","OPCION_A":"Porque aprender y ajustar conductas saludables requiere continuidad y reflexión, no una sola charla.","OPCION_B":"Para escuchar dudas y experiencias de la comunidad, además de compartir información.","OPCION_C":"Porque la posibilidad de practicarla depende también de recursos, costumbres y condiciones de vida.","OPCION_D":"Porque los hábitos también dependen del entorno y de condiciones sociales; la educación debe acompañarse de acciones más amplias.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Porque la posibilidad de practicarla depende también de recursos, costumbres y condiciones de vida.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"facil","PREGUNTA":"¿Qué nivel de vida busca sostener la educación para la salud en la persona y su entorno?","OPCION_A":"El enfoque biopsicosocial.","OPCION_B":"Un estilo de vida saludable con cuidado personal, familiar y comunitario.","OPCION_C":"El contexto cultural y social en el que las personas aprenden y toman decisiones.","OPCION_D":"Que las personas desarrollen habilidades y adopten prácticas saludables de manera sostenida.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Un estilo de vida saludable con cuidado personal, familiar y comunitario.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"educacion en salud","DIFICULTAD":"facil","PREGUNTA":"Una comunidad identifica sus problemas y propone soluciones con el equipo de salud. ¿Qué papel desempeña?","OPCION_A":"Participa activamente en su aprendizaje y en el cuidado colectivo de la salud.","OPCION_B":"Pasa de la información a una habilidad y una práctica concreta.","OPCION_C":"Capacidad de autogestión y mayor control sobre los factores que afectan su bienestar.","OPCION_D":"Fortalece capacidades personales y comunitarias para mejorar condiciones de bienestar.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Participa activamente en su aprendizaje y en el cuidado colectivo de la salud.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–16"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"¿Cómo veía la salud el enfoque biomédico clásico?","OPCION_A":"Principalmente como ausencia de enfermedad, con énfasis en diagnóstico y tratamiento.","OPCION_B":"Puede modificar riesgos, servicios y condiciones de vida de toda la población.","OPCION_C":"Actuar sobre diferencias evitables e injustas para que todas las personas tengan oportunidades de bienestar.","OPCION_D":"Requiere prevención, hábitos saludables y trabajo con los factores de riesgo de la comunidad.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Principalmente como ausencia de enfermedad, con énfasis en diagnóstico y tratamiento.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"¿Qué añadió el enfoque biopsicosocial a la idea de salud?","OPCION_A":"El individual pertenece a la persona, como edad o genética; el ambiental corresponde al entorno, como aire, agua o vivienda.","OPCION_B":"Los determinantes sociales y ambientales de la salud.","OPCION_C":"La interacción de factores biológicos, psicológicos y sociales.","OPCION_D":"La demográfica y la epidemiológica.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La interacción de factores biológicos, psicológicos y sociales.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"Según la definición de la OMS citada en el material, ¿qué tres dimensiones integran el bienestar?","OPCION_A":"La demográfica y la epidemiológica.","OPCION_B":"Los determinantes sociales y ambientales de la salud.","OPCION_C":"La interacción de factores biológicos, psicológicos y sociales.","OPCION_D":"La física, la mental y la social.","RESPUESTA_CORRECTA":"D","EXPLICACION":"La física, la mental y la social.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"dificil","PREGUNTA":"Una persona tiene trabajo inseguro y mala vivienda. ¿Por qué eso importa para su salud?","OPCION_A":"Porque empleo y vivienda son determinantes sociales que condicionan cómo vive y enferma.","OPCION_B":"Porque todas las personas deben tener oportunidades y condiciones dignas para alcanzar bienestar.","OPCION_C":"Porque el bienestar también incluye dimensiones psicológicas, sociales y la capacidad de adaptarse al entorno.","OPCION_D":"Porque el agua y el saneamiento son determinantes de la salud.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Porque empleo y vivienda son determinantes sociales que condicionan cómo vive y enferma.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"¿En qué momentos de la vida influyen los determinantes sociales?","OPCION_A":"En las condiciones en que las personas nacen, crecen, trabajan y envejecen.","OPCION_B":"En las mismas unidades que la variable original.","OPCION_C":"En crear condiciones y capacidades que favorezcan el bienestar de la población.","OPCION_D":"En los resultados obtenidos e interpretados, no en suposiciones ajenas al estudio.","RESPUESTA_CORRECTA":"A","EXPLICACION":"En las condiciones en que las personas nacen, crecen, trabajan y envejecen.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"dificil","PREGUNTA":"¿Qué diferencia hay entre un factor individual y uno ambiental?","OPCION_A":"La interacción de factores biológicos, psicológicos y sociales.","OPCION_B":"El individual pertenece a la persona, como edad o genética; el ambiental corresponde al entorno, como aire, agua o vivienda.","OPCION_C":"Los determinantes sociales y ambientales de la salud.","OPCION_D":"La demográfica y la epidemiológica.","RESPUESTA_CORRECTA":"B","EXPLICACION":"El individual pertenece a la persona, como edad o genética; el ambiental corresponde al entorno, como aire, agua o vivienda.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"¿El hábito de fumar es un determinante conductual o político?","OPCION_A":"Políticas, distribución de la riqueza y educación.","OPCION_B":"Puede modificar riesgos, servicios y condiciones de vida de toda la población.","OPCION_C":"Conductual, porque forma parte de las prácticas de la persona.","OPCION_D":"Principalmente como ausencia de enfermedad, con énfasis en diagnóstico y tratamiento.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Conductual, porque forma parte de las prácticas de la persona.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"¿Cómo puede una ley influir en la salud aunque no sea un tratamiento médico?","OPCION_A":"Principalmente como ausencia de enfermedad, con énfasis en diagnóstico y tratamiento.","OPCION_B":"Puede modificar riesgos, servicios y condiciones de vida de toda la población.","OPCION_C":"Actuar sobre diferencias evitables e injustas para que todas las personas tengan oportunidades de bienestar.","OPCION_D":"Requiere prevención, hábitos saludables y trabajo con los factores de riesgo de la comunidad.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Puede modificar riesgos, servicios y condiciones de vida de toda la población.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"¿Qué distingue una inequidad en salud de cualquier diferencia entre personas?","OPCION_A":"Que la población acceda a servicios adecuados y que las intervenciones se evalúen.","OPCION_B":"Que la salud también depende de condiciones del entorno, no solo de decisiones individuales.","OPCION_C":"Actuar sobre diferencias evitables e injustas para que todas las personas tengan oportunidades de bienestar.","OPCION_D":"Que la inequidad es una diferencia injusta y evitable vinculada a condiciones desiguales.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Que la inequidad es una diferencia injusta y evitable vinculada a condiciones desiguales.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"Un barrio tiene agua segura y otro no. ¿Qué medida apunta a la equidad?","OPCION_A":"Actuar sobre diferencias evitables e injustas para que todas las personas tengan oportunidades de bienestar.","OPCION_B":"Requiere prevención, hábitos saludables y trabajo con los factores de riesgo de la comunidad.","OPCION_C":"Disminuye el peso relativo de infecciones y aumentan las enfermedades crónicas no transmisibles.","OPCION_D":"Actuar sobre esa diferencia para que ambos tengan una oportunidad similar de mantenerse sanos.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Actuar sobre esa diferencia para que ambos tengan una oportunidad similar de mantenerse sanos.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"facil","PREGUNTA":"¿Qué sucede con las enfermedades predominantes durante la transición epidemiológica descrita en el PDF?","OPCION_A":"Actuar sobre diferencias evitables e injustas para que todas las personas tengan oportunidades de bienestar.","OPCION_B":"Disminuye el peso relativo de infecciones y aumentan las enfermedades crónicas no transmisibles.","OPCION_C":"Políticas, distribución de la riqueza y educación.","OPCION_D":"Requiere prevención, hábitos saludables y trabajo con los factores de riesgo de la comunidad.","RESPUESTA_CORRECTA":"B","EXPLICACION":"Disminuye el peso relativo de infecciones y aumentan las enfermedades crónicas no transmisibles.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"medio","PREGUNTA":"Si la población vive más años y cambian las principales causas de muerte, ¿qué dos transiciones se relacionan?","OPCION_A":"La física, la mental y la social.","OPCION_B":"Los determinantes sociales y ambientales de la salud.","OPCION_C":"La demográfica y la epidemiológica.","OPCION_D":"La interacción de factores biológicos, psicológicos y sociales.","RESPUESTA_CORRECTA":"C","EXPLICACION":"La demográfica y la epidemiológica.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"2–4"},{"MATERIA":"SALUD PUBLICA","TEMA":"concepto de salud y determinantes","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué el aumento de enfermedades crónicas exige algo más que atención hospitalaria?","OPCION_A":"Disminuye el peso relativo de infecciones y aumentan las enfermedades crónicas no transmisibles.","OPCION_B":"Requiere prevención, hábitos saludables y trabajo con los factores de riesgo de la comunidad.","OPCION_C":"Actuar sobre esa diferencia para que ambos tengan una oportunidad similar de mantenerse sanos.","OPCION_D":"Principalmente como ausencia de enfermedad, con énfasis en diagnóstico y tratamiento.","RESPU